import datetime, json, re
HOL = set(['2026-10-16', '2026-11-02', '2026-11-21', '2026-12-08', '2026-12-24', '2026-12-25', '2026-12-26', '2026-12-31'])
BWD = set([0, 1, 2, 3, 4, 5])
WDRULE = 'first_after'
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MO = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
def isbd(d):
    return d.weekday() in BWD and d.isoformat() not in HOL
def txt(d):
    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MO[d.month - 1] + ' ' + str(d.year)
def txt_short(d):
    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MO[d.month - 1]
def addbd(d, n):
    c = 0
    guard = 0
    while c < n and guard < 4000:
        d = d + datetime.timedelta(days=1)
        guard += 1
        if isbd(d):
            c += 1
    return d
def next_bd(d):
    guard = 0
    while not isbd(d) and guard < 4000:
        d = d + datetime.timedelta(days=1)
        guard += 1
    return d
def prev_bd(d):
    guard = 0
    while not isbd(d) and guard < 4000:
        d = d - datetime.timedelta(days=1)
        guard += 1
    return d
def lastbd_of_week(monday):
    for k in range(6, -1, -1):
        d = monday + datetime.timedelta(days=k)
        if isbd(d):
            return d
    return None
def weekday_table(today):
    monday = today - datetime.timedelta(days=today.weekday())
    tab = []
    for i in range(7):
        a = monday + datetime.timedelta(days=i)
        b = a + datetime.timedelta(days=7)
        t1 = '"this ' + WD[i] + '" = ' + txt(a) + (' (already past)' if a < today else '')
        tab.append(t1 + '; "next ' + WD[i] + '" = ' + txt(b))
    return '\n'.join(tab)
def weekday_table_first_after(today):
    tab = []
    for k in range(1, 8):
        a = today + datetime.timedelta(days=k)
        tab.append('"this ' + WD[a.weekday()] + '" = "next ' + WD[a.weekday()] + '" = ' + txt(a))
    return '\n'.join(tab)
if WDRULE == 'first_after':
    weekday_table = weekday_table_first_after
def calendar_text(today, deadline, extra_days=10):
    cal = []
    d = today
    while d <= deadline + datetime.timedelta(days=extra_days):
        if d > deadline:
            tag = 'AFTER THE DEADLINE, not allowed'
        elif isbd(d):
            tag = 'allowed'
        elif d.weekday() not in BWD:
            tag = 'not a business day (' + WD[d.weekday()] + '), not allowed'
        else:
            tag = 'bank holiday, not allowed'
        nb = next_bd(d)
        extra = ''
        if tag.startswith('not a business day') or tag.startswith('bank'):
            extra = ' -> next business day ' + txt_short(nb) + ' (' + nb.isoformat() + ')' + ('' if nb <= deadline else ', which is after the deadline: offer the deadline instead')
        cal.append(d.isoformat() + ' ' + txt_short(d) + ('  (today)' if d == today else '') + ': ' + tag + extra)
        d = d + datetime.timedelta(days=1)
    return '\n'.join(cal)
def fmt(x):
    try:
        x = float(x)
    except Exception:
        return str(x)
    s = '%.2f' % x
    return s[:-3] if s.endswith('.00') else s
try:
    raw = str(vars.get('now') or '').strip()
    try:
        nowdt = datetime.datetime.fromisoformat(raw[:16])
    except Exception:
        nowdt = datetime.datetime.fromisoformat(raw[:10] + 'T09:00')
    today = nowdt.date()
    vars['today_iso'] = today.isoformat()
    vars['today_text'] = txt(today)
    vars['now_time'] = nowdt.strftime('%H:%M')
    vars['weekday_table'] = weekday_table(today)
    lines = []
    cur = nowdt.strftime('%H:%M')
    if cur < '18:00':
        start = '09:00' if cur < '09:00' else 'after ' + cur
        lines.append('Today, ' + txt(today) + ' (' + today.isoformat() + '), from ' + start + ' up to 18:00.')
    nbd = today
    for _i in range(2):
        nbd = addbd(nbd, 1)
        lines.append(txt(nbd) + ' (' + nbd.isoformat() + '), from 09:00 up to 18:00 included.')
    tom = today + datetime.timedelta(days=1)
    extra = 'Tomorrow is ' + txt(tom) + '.'
    if not isbd(tom):
        extra += ' Tomorrow is NOT allowed, it is not a business day.'
    vars['callback_text'] = 'The ONLY allowed callback times are:\n- ' + '\n- '.join(lines) + '\n' + extra + ' Any other day or time is outside the window.'
    if str(vars.get('who1') or '') == 'customer':
        vars['outcome'] = 'not_verified'
        vars['reason'] = 'withheld'
    else:
        vars['outcome'] = 'not_reached'
        vars['reason'] = 'unconfirmed'
    vars['setup_state'] = 'ok'
except Exception as e:
    vars['setup_state'] = 'error ' + str(e)
    vars.setdefault('callback_text', 'Callbacks: today later than now up to 18:00, or the next business day from 09:00 to 18:00.')
    vars.setdefault('today_text', str(vars.get('now')))
    vars.setdefault('today_iso', str(vars.get('now'))[:10])
    vars.setdefault('now_time', '')
    vars.setdefault('weekday_table', '')

try:
    rec = str(vars.get('recorded_pids') or '').strip()
    if True and rec and rec.lower() not in ('none', 'null'):
        vars['outcome'] = 'promise'
        vars['reason'] = str(vars.get('promise_reason') or '')
        if vars['reason'].lower() in ('none', 'null'):
            vars['reason'] = ''
    else:
        vars['outcome'] = 'not_reached'
        vars['reason'] = 'scheduled'
except Exception:
    pass
